// Filter to only unpaid invoices that need action
const today = new Date();
const invoices = $input.all();
const actionable = [];

for (const item of invoices) {
  const inv = item.json;
  if (inv.status === 'paid' || inv.status === 'cancelled') continue;

  const dueDate = new Date(inv.due_date);
  const diffMs = today - dueDate;
  const daysOverdue = Math.floor(diffMs / (1000 * 60 * 60 * 24));
  const daysUntilDue = -daysOverdue;

  let actionType = null;
  if (daysUntilDue === 1) actionType = 'reminder_due_tomorrow';
  else if (daysOverdue === 1) actionType = 'followup_1_day_overdue';
  else if (daysOverdue === 7) actionType = 'notice_7_days_overdue';
  else if (daysOverdue === 14) actionType = 'final_notice_14_days';

  if (actionType) {
    actionable.push({
      json: {
        ...inv,
        days_overdue: daysOverdue,
        days_until_due: daysUntilDue,
        action_type: actionType
      }
    });
  }
}

return actionable.length > 0 ? actionable : [{ json: { no_action_needed: true } }];

