// Parse Claude's JSON response
const claudeResponse = $input.item.json.content || $input.item.json.text || $input.item.json.output || '';
let emailContent;
try {
  const jsonMatch = claudeResponse.match(/\{[\s\S]*\}/);
  emailContent = jsonMatch ? JSON.parse(jsonMatch[0]) : { subject: 'Invoice Follow-up', body: claudeResponse, urgency: 'medium' };
} catch(e) {
  emailContent = { subject: 'Invoice Follow-up', body: claudeResponse, urgency: 'medium' };
}

return {
  json: {
    ...emailContent,
    client_email: $('filter-actionable-invoices').item.json.client_email,
    client_name: $('filter-actionable-invoices').item.json.client_name,
    invoice_id: $('filter-actionable-invoices').item.json.invoice_id,
    action_type: $('filter-actionable-invoices').item.json.action_type,
    days_overdue: $('filter-actionable-invoices').item.json.days_overdue,
    amount_due: $('filter-actionable-invoices').item.json.amount_due,
    client_phone: $('filter-actionable-invoices').item.json.client_phone
  }
};

