// Build morning WhatsApp summary for owner
const allInvoices = $input.all();
const totalPending = allInvoices.filter(i => i.json.action_type).length;
const overdue = allInvoices.filter(i => i.json.days_overdue > 0);
const totalOverdueAmount = overdue.reduce((sum, i) => sum + parseFloat(i.json.amount_due || 0), 0);

const summary = `📊 Morning Invoice Summary — ${new Date().toLocaleDateString('en-AU')}

Actions taken today: ${totalPending}
Overdue invoices: ${overdue.length}
Total overdue amount: $${totalOverdueAmount.toFixed(2)}

Top overdue:
${overdue.slice(0, 3).map(i => `• ${i.json.client_name}: $${i.json.amount_due} (${i.json.days_overdue}d overdue)`).join('\n')}`;

return [{ json: { summary } }];
